    private fun item(
        id: String,
        level: Int,
        category: String,
        sentence: String,
        cards: List<String>,
        distractors: List<String>,
        hint: String = "Find the card that makes the next part of the sentence."
    ): SentenceItem {
        return SentenceItem(
            id = id,
            level = level,
            category = category,
            sentence = sentence,
            cards = cards,
            correctOrder = cards,
            distractors = distractors,
            hint = hint
        )
    }
